changeSet.sql:
DO $$
BEGIN
    -- Eski template_data → template_data_uz (backward-compat: mavjud qatorlar uz sifatida saqlanadi)
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='contract_template' AND column_name='template_data') THEN
        ALTER TABLE document.contract_template RENAME COLUMN template_data TO template_data_uz;
    END IF;
    -- Ru va En yangi ustunlar (idempotent)
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='contract_template' AND column_name='template_data_ru') THEN
        ALTER TABLE document.contract_template ADD COLUMN template_data_ru TEXT;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='document' AND table_name='contract_template' AND column_name='template_data_en') THEN
        ALTER TABLE document.contract_template ADD COLUMN template_data_en TEXT;
    END IF;
END $$;
